<template>
 <div class="dashboard" :style="{width:'100%','--board-height':height+'px'}" v-loading="loading">
  <header class="dashboard-header"><div class="brand"><span class="brand-mark"><i/><b/></span><strong>贵金属加工系统</strong></div><div class="dashboard-factory"><span>数据范围</span><el-select v-model="selectedFactory" aria-label="看板工厂" filterable :disabled="!canSelectAll||!factoryOptions.length" placeholder="所属工厂" @change="load"><el-option v-if="canSelectAll" label="全部工厂（汇总）" value=""/><el-option v-for="factory in factoryOptions" :key="factory.id" :label="factory.name" :value="factory.id"/></el-select></div><div class="header-right"><el-button class="backend-button" :disabled="!managementPath" @click="router.push(managementPath)">后台管理</el-button><el-dropdown trigger="click" placement="bottom-end" @command="logout"><span class="profile" role="button" tabindex="0" aria-label="账户菜单"><span class="avatar"><i/><b/></span>{{user.nickName||user.name}}</span><template #dropdown><el-dropdown-menu><el-dropdown-item command="logout">退出登录</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></header>
  <main><div v-if="failed" class="load-error">数据加载失败 <el-button link @click="load">重新加载</el-button></div>
   <div class="summary-row"><div class="summary-card"><div>工单统计</div><strong>{{data.workOrders?.total??0}}<small>单</small></strong><p>进行中 {{data.workOrders?.inProgress??0}}　　已完成 {{data.workOrders?.completed??0}}</p></div><div class="summary-card"><div>今日预警统计</div><strong>{{data.warnings?.pending??0}}<small>条待处理</small></strong><p>今日新增{{data.warnings?.newToday??0}}　已处理{{data.warnings?.handledToday??0}}</p></div><div class="summary-card quotation-summary"><div>本月报价单</div><strong>{{data.quotations?.count??0}}<small>单</small></strong><p class="quotation-category-counts" :title="quotationCategoryText"><template v-if="data.quotations?.categories?.length"><span>覆盖产品：</span><span v-for="category in data.quotations.categories" :key="category" class="quotation-category">{{category}}：{{data.quotations.categoryCounts?.[category]??0}}单</span></template><span v-else>覆盖产品：暂无</span></p></div></div>
   <div class="top-charts"><section class="chart-card trend-card"><h2>近30日金属损耗趋势</h2><div ref="trendEl" class="dashboard-chart"/><span v-if="!hasTrend" class="empty-overlay">近30日暂无已结算损耗</span></section><section class="chart-card"><h2>本月工序损耗排行TOP5 <span>单位：g</span></h2><div ref="rankingEl" class="dashboard-chart"/><span v-if="!data.ranking?.length" class="empty-overlay">本月暂无工序损耗</span></section></div>
   <div class="bottom-charts"><section class="chart-card"><h2>本月各工厂损耗对比 <span>g</span></h2><div ref="factoryEl" class="dashboard-chart"/></section><section class="chart-card"><h2>本月预警统计分布</h2><div ref="distributionEl" class="dashboard-chart"/><span v-if="!data.distribution?.length" class="empty-overlay">本月暂无预警</span></section><section class="chart-card warning-center"><h2>预警中心 <el-button v-if="can('metal:warning-record:list')" link @click="router.push('/metal/warning-record')">更多&gt;&gt;</el-button></h2><el-table :data="data.warningCenter||[]" border empty-text="暂无预警" class="warning-table"><el-table-column label="预警时间" prop="triggerTime" :formatter="dateTimeCell" min-width="110"/><el-table-column label="工厂名称" prop="factoryName" min-width="90"/><el-table-column label="工序名称" prop="processName" min-width="80"/><el-table-column label="预警值" prop="thresholdValue" width="78"/><el-table-column label="状态" width="78"><template #default="{row}">{{row.status==='PENDING'?'待处理':'已处理'}}</template></el-table-column></el-table></section></div>
  </main>
 </div>
</template>
<script setup lang="ts">
import {getToken} from '@/utils/auth'
import {dateTimeCell} from '@/utils/display-date-time'
import{ref,computed,nextTick,onMounted,onBeforeUnmount,watch}from'vue'
import{useRouter}from'vue-router'
import{useWindowSize}from'@vueuse/core'
import{ElMessageBox}from'element-plus'
import * as echarts from'echarts'
import useUserStore from'@/store/modules/user'
import request from'@/utils/request'
const user=useUserStore(),router=useRouter(),{width,height}=useWindowSize(),loading=ref(false),failed=ref(false),data=ref<Record<string,any>>({}),trendEl=ref<HTMLElement>(),rankingEl=ref<HTMLElement>(),factoryEl=ref<HTMLElement>(),distributionEl=ref<HTMLElement>(),instances:echarts.ECharts[]=[]
const can=(p:string)=>user.permissions.includes('*:*:*')||user.permissions.includes(p),managementPath=computed(()=>[{path:'/metal/factory',permission:'metal:factory:list'},{path:'/metal/work-order',permission:'metal:work-order:list'},{path:'/metal/inventory',permission:'metal:inventory:list'},{path:'/metal/product',permission:'metal:product:list'},{path:'/metal/quotation',permission:'metal:quotation:list'},{path:'/system/user',permission:'system:user:list'}].find(x=>can(x.permission))?.path||''),hasTrend=computed(()=>data.value.trend?.some((x:any)=>Number(x.loss)!==0))
const selectedFactory=ref(''),factoryOptions=ref<{id:string;name:string}[]>([]),canSelectAll=ref(false),optionsReady=ref(false)
let loadEpoch=0,disposed=false
const quotationCategoryText=computed(()=>(data.value.quotations?.categories??[]).map((category:string)=>category+'：'+(data.value.quotations.categoryCounts?.[category]??0)+'单').join('；'))
const blue='#4f83ff',teal='#76b9c4',font={fontFamily:'Arial, Microsoft YaHei',fontSize:12,color:'#303133'}
function render(){instances.forEach(chart=>chart.dispose());instances.length=0;const d=data.value;const create=(el:HTMLElement|undefined,option:echarts.EChartsOption)=>{if(!el)return;const chart=echarts.init(el);chart.setOption({...option,textStyle:font,animation:false});instances.push(chart)}
 create(trendEl.value,{color:[blue],legend:{top:0,data:['铱Ir']},tooltip:{trigger:'axis',valueFormatter:v=>String(v)+' g'},grid:{left:55,right:25,top:50,bottom:35},xAxis:{type:'category',boundaryGap:false,data:(d.trend||[]).map((x:any)=>x.day.slice(5))},yAxis:{type:'value',name:'g',min:0},series:[{name:'铱Ir',type:'line',symbolSize:4,data:(d.trend||[]).map((x:any)=>Number(x.loss)),lineStyle:{width:2}}]})
 create(rankingEl.value,{color:[blue],legend:{top:0,data:['铱Ir']},tooltip:{trigger:'axis',valueFormatter:v=>String(v)+' g'},grid:{left:85,right:25,top:50,bottom:35},xAxis:{type:'value',min:0},yAxis:{type:'category',inverse:true,data:(d.ranking||[]).map((x:any)=>x.processName),axisLabel:{width:65,overflow:'truncate'}},series:[{name:'铱Ir',type:'bar',barWidth:12,data:(d.ranking||[]).map((x:any)=>Number(x.loss))}]})
 create(factoryEl.value,{color:[blue],tooltip:{trigger:'axis',valueFormatter:v=>String(v)+' g'},grid:{left:50,right:20,top:35,bottom:60},xAxis:{type:'category',data:(d.factories||[]).map((x:any)=>x.factoryName),axisLabel:{interval:0,rotate:25,width:70,overflow:'truncate'}},yAxis:{type:'value',min:0},series:[{type:'bar',barMaxWidth:36,data:(d.factories||[]).map((x:any)=>Number(x.loss))}]})
 create(distributionEl.value,{color:['#2e4c9a','#366efa','#7597ed','#76b9c4','#9c70fa','#f5db59'],tooltip:{trigger:'item',formatter:'{b}<br/>{c} 条（{d}%）'},legend:{orient:'vertical',right:5,top:'center',textStyle:{...font,width:70,overflow:'truncate'}},series:[{type:'pie',radius:'68%',center:['42%','57%'],label:{position:'inside',formatter:'{d}%',color:'white'},data:(d.distribution||[]).map((x:any)=>({name:x.factoryName,value:Number(x.count)}))}]})
}
async function load(){
 const current=++loadEpoch;loading.value=true;failed.value=false;data.value={};await nextTick();if(disposed||current!==loadEpoch)return;render()
 try{
  if(!optionsReady.value){const options=(await request({url:'/metal/dashboard/factories'})).data;if(disposed||current!==loadEpoch)return;factoryOptions.value=options.factories;canSelectAll.value=options.canSelectAll;selectedFactory.value=canSelectAll.value?'':factoryOptions.value[0]?.id??'';optionsReady.value=true}
  const response=await request({url:'/metal/dashboard',params:selectedFactory.value?{factoryId:selectedFactory.value}:{}})
  if(disposed||current!==loadEpoch)return;data.value=response.data;await nextTick();if(!disposed&&current===loadEpoch)render()
 }catch{if(!disposed&&current===loadEpoch){failed.value=true;data.value={}}}finally{if(!disposed&&current===loadEpoch)loading.value=false}
}
async function logout(){const token=getToken();try{await ElMessageBox.confirm('确认退出系统？','提示')}catch{return}if(await user.logOut(token))await router.push('/login')}
watch([width,height],()=>nextTick(()=>instances.forEach(chart=>chart.resize())))
onMounted(load);onBeforeUnmount(()=>{disposed=true;loadEpoch++;instances.forEach(chart=>chart.dispose())})
</script>
<style scoped>
